<script>
(function(){
"use strict";

/* ===================== CHIP-8 CORE ===================== */

const FONTSET = [
  0xF0,0x90,0x90,0x90,0xF0, // 0
  0x20,0x60,0x20,0x20,0x70, // 1
  0xF0,0x10,0xF0,0x80,0xF0, // 2
  0xF0,0x10,0xF0,0x10,0xF0, // 3
  0x90,0x90,0xF0,0x10,0x10, // 4
  0xF0,0x80,0xF0,0x10,0xF0, // 5
  0xF0,0x80,0xF0,0x90,0xF0, // 6
  0xF0,0x10,0x20,0x40,0x40, // 7
  0xF0,0x90,0xF0,0x90,0xF0, // 8
  0xF0,0x90,0xF0,0x10,0xF0, // 9
  0xF0,0x90,0xF0,0x90,0x90, // A
  0xE0,0x90,0xE0,0x90,0xE0, // B
  0xF0,0x80,0x80,0x80,0xF0, // C
  0xE0,0x90,0x90,0x90,0xE0, // D
  0xF0,0x80,0xF0,0x80,0xF0, // E
  0xF0,0x80,0xF0,0x80,0x80  // F
];

/*
  Hand-assembled demo ROM.
  Draws the '0' font glyph (sprite at 0x050, height 5) at (10,12).
  Key 4 (keyboard Q) moves it left, key 6 (keyboard E) moves it right.
  Loop:
    erase/draw at current pos (toggle)
    if key 4 down -> X--
    if key 6 down -> X++
    draw at (possibly new) pos
    jump to loop
*/
const DEMO_ROM = new Uint8Array([
  0xA0,0x50, // LD I, 0x050        I = font '0'
  0x61,0x0C, // LD V1, 12          Y = 12
  0x60,0x0A, // LD V0, 10          X = 10
  0x64,0x04, // LD V4, 4           left key code
  0x66,0x06, // LD V6, 6           right key code
  0xD0,0x15, // LOOP: DRW V0,V1,5  toggle sprite
  0xE4,0x9E, // SKP V4             skip next if left key pressed
  0x12,0x12, // JP 0x212           (no left) -> check right
  0x70,0xFF, // ADD V0, -1         X--
  0xE6,0x9E, // SKP V6             skip next if right key pressed
  0x12,0x18, // JP 0x218           (no right) -> draw
  0x70,0x01, // ADD V0, 1          X++
  0xD0,0x15, // DRW V0,V1,5        draw at (new) pos
  0x12,0x0A  // JP 0x20A           back to LOOP
]);

const KEYMAP = {
  '1':0x1,'2':0x2,'3':0x3,'4':0xC,
  'q':0x4,'w':0x5,'e':0x6,'r':0xD,
  'a':0x7,'s':0x8,'d':0x9,'f':0xE,
  'z':0xA,'x':0x0,'c':0xB,'v':0xF
};
const KEYPAD_LAYOUT = [
  ['1','2','3','4'],
  ['Q','W','E','R'],
  ['A','S','D','F'],
  ['Z','X','C','V']
];

class Chip8 {
  constructor(){
    this.reset();
  }
  reset(){
    this.mem = new Uint8Array(4096);
    for(let i=0;i<FONTSET.length;i++) this.mem[0x050+i] = FONTSET[i];
    this.V = new Uint8Array(16);
    this.I = 0;
    this.pc = 0x200;
    this.stack = [];
    this.dt = 0;
    this.st = 0;
    this.display = new Uint8Array(64*32);
    this.keys = new Uint8Array(16);
    this.waitingKeyReg = -1;
    this.halted = false;
    this.lastOpcode = 0;
    this.drawFlag = true;
  }
  loadRom(bytes){
    this.reset();
    for(let i=0;i<bytes.length && (0x200+i)<4096;i++){
      this.mem[0x200+i] = bytes[i];
    }
  }
  tickTimers(){
    if(this.dt>0) this.dt--;
    if(this.st>0) this.st--;
  }
  // Execute one instruction. Returns decoded opcode for debugger.
  step(){
    if(this.halted) return null;
    if(this.pc>4094){ this.halted = true; return null; }
    const opcode = (this.mem[this.pc]<<8) | this.mem[this.pc+1];
    this.lastOpcode = opcode;
    this.pc += 2;

    const x   = (opcode & 0x0F00) >> 8;
    const y   = (opcode & 0x00F0) >> 4;
    const n   = opcode & 0x000F;
    const nn  = opcode & 0x00FF;
    const nnn = opcode & 0x0FFF;

    switch(opcode & 0xF000){
      case 0x0000:
        if(opcode === 0x00E0){ // CLS
          this.display.fill(0);
          this.drawFlag = true;
        } else if(opcode === 0x00EE){ // RET
          this.pc = this.stack.pop() ?? 0x200;
        }
        // 0NNN (call machine code) intentionally ignored
        break;
      case 0x1000: // JP addr
        this.pc = nnn;
        break;
      case 0x2000: // CALL addr
        this.stack.push(this.pc);
        this.pc = nnn;
        break;
      case 0x3000: // SE Vx, byte
        if(this.V[x] === nn) this.pc += 2;
        break;
      case 0x4000: // SNE Vx, byte
        if(this.V[x] !== nn) this.pc += 2;
        break;
      case 0x5000: // SE Vx, Vy
        if(n===0 && this.V[x] === this.V[y]) this.pc += 2;
        break;
      case 0x6000: // LD Vx, byte
        this.V[x] = nn;
        break;
      case 0x7000: // ADD Vx, byte
        this.V[x] = (this.V[x] + nn) & 0xFF;
        break;
      case 0x8000:{
        switch(n){
          case 0x0: this.V[x] = this.V[y]; break;                         // LD
          case 0x1: this.V[x] = this.V[x] | this.V[y]; this.V[0xF]=0; break; // OR
          case 0x2: this.V[x] = this.V[x] & this.V[y]; this.V[0xF]=0; break; // AND
          case 0x3: this.V[x] = this.V[x] ^ this.V[y]; this.V[0xF]=0; break; // XOR
          case 0x4:{ // ADD Vx,Vy with carry
            const sum = this.V[x] + this.V[y];
            this.V[x] = sum & 0xFF;
            this.V[0xF] = sum > 0xFF ? 1 : 0;
            break;
          }
          case 0x5:{ // SUB Vx,Vy
            const vx=this.V[x], vy=this.V[y];
            this.V[x] = (vx - vy) & 0xFF;
            this.V[0xF] = vx >= vy ? 1 : 0;
            break;
          }
          case 0x6:{ // SHR Vx
            const vx = this.V[x];
            this.V[x] = (vx >> 1) & 0xFF;
            this.V[0xF] = vx & 0x1;
            break;
          }
          case 0x7:{ // SUBN Vx,Vy
            const vx=this.V[x], vy=this.V[y];
            this.V[x] = (vy - vx) & 0xFF;
            this.V[0xF] = vy >= vx ? 1 : 0;
            break;
          }
          case 0xE:{ // SHL Vx
            const vx = this.V[x];
            this.V[x] = (vx << 1) & 0xFF;
            this.V[0xF] = (vx & 0x80) ? 1 : 0;
            break;
          }
        }
        break;
      }
      case 0x9000: // SNE Vx, Vy
        if(n===0 && this.V[x] !== this.V[y]) this.pc += 2;
        break;
      case 0xA000: // LD I, addr
        this.I = nnn;
        break;
      case 0xB000: // JP V0, addr
        this.pc = (nnn + this.V[0]) & 0xFFF;
        break;
      case 0xC000: // RND Vx, byte
        this.V[x] = (Math.floor(Math.random()*256)) & nn;
        break;
      case 0xD000:{ // DRW Vx,Vy,n
        const vx = this.V[x] & 63;
        const vy = this.V[y] & 31;
        this.V[0xF] = 0;
        for(let row=0; row<n; row++){
          const spriteByte = this.mem[(this.I+row) & 0xFFF];
          const py = vy+row;
          if(py>=32) break;
          for(let col=0; col<8; col++){
            const px = vx+col;
            if(px>=64) break;
            const bit = (spriteByte >> (7-col)) & 1;
            if(bit){
              const idx = py*64+px;
              if(this.display[idx]===1) this.V[0xF]=1;
              this.display[idx] ^= 1;
            }
          }
        }
        this.drawFlag = true;
        break;
      }
      case 0xE000:
        if(nn===0x9E){ if(this.keys[this.V[x] & 0xF]) this.pc += 2; }
        else if(nn===0xA1){ if(!this.keys[this.V[x] & 0xF]) this.pc += 2; }
        break;
      case 0xF000:
        switch(nn){
          case 0x07: this.V[x] = this.dt; break;
          case 0x0A: // LD Vx, K (blocking wait for key)
            this.waitingKeyReg = x;
            this.pc -= 2; // re-run this instruction until a key arrives
            break;
          case 0x15: this.dt = this.V[x]; break;
          case 0x18: this.st = this.V[x]; break;
          case 0x1E: this.I = (this.I + this.V[x]) & 0xFFF; break;
          case 0x29: this.I = (0x050 + (this.V[x] & 0xF) * 5) & 0xFFF; break;
          case 0x33:{ // BCD
            const v = this.V[x];
            this.mem[this.I & 0xFFF]   = Math.floor(v/100);
            this.mem[(this.I+1)&0xFFF] = Math.floor(v/10)%10;
            this.mem[(this.I+2)&0xFFF] = v%10;
            break;
          }
          case 0x55: // LD [I], V0..Vx
            for(let i=0;i<=x;i++) this.mem[(this.I+i)&0xFFF] = this.V[i];
            this.I = (this.I + x + 1) & 0xFFF;
            break;
          case 0x65: // LD V0..Vx, [I]
            for(let i=0;i<=x;i++) this.V[i] = this.mem[(this.I+i)&0xFFF];
            this.I = (this.I + x + 1) & 0xFFF;
            break;
        }
        break;
      default:
        break;
    }
    return opcode;
  }
  // If waiting for a key, call this when a key goes down.
  provideKey(k){
    if(this.waitingKeyReg>=0){
      this.V[this.waitingKeyReg] = k;
      this.waitingKeyReg = -1;
    }
  }
}

/* ===================== DISASSEMBLER (for debugger display) ===================== */
function disassemble(opcode){
  const x   = (opcode & 0x0F00) >> 8;
  const y   = (opcode & 0x00F0) >> 4;
  const n   = opcode & 0x000F;
  const nn  = opcode & 0x00FF;
  const nnn = opcode & 0x0FFF;
  const h = v => '0x'+v.toString(16).toUpperCase().padStart(2,'0');
  switch(opcode & 0xF000){
    case 0x0000:
      if(opcode===0x00E0) return 'CLS';
      if(opcode===0x00EE) return 'RET';
      return 'SYS '+nnn.toString(16);
    case 0x1000: return `JP 0x${nnn.toString(16).toUpperCase()}`;
    case 0x2000: return `CALL 0x${nnn.toString(16).toUpperCase()}`;
    case 0x3000: return `SE V${x.toString(16)}, ${h(nn)}`;
    case 0x4000: return `SNE V${x.toString(16)}, ${h(nn)}`;
    case 0x5000: return `SE V${x.toString(16)}, V${y.toString(16)}`;
    case 0x6000: return `LD V${x.toString(16)}, ${h(nn)}`;
    case 0x7000: return `ADD V${x.toString(16)}, ${h(nn)}`;
    case 0x8000:
      switch(n){
        case 0x0: return `LD V${x.toString(16)}, V${y.toString(16)}`;
        case 0x1: return `OR V${x.toString(16)}, V${y.toString(16)}`;
        case 0x2: return `AND V${x.toString(16)}, V${y.toString(16)}`;
        case 0x3: return `XOR V${x.toString(16)}, V${y.toString(16)}`;
        case 0x4: return `ADD V${x.toString(16)}, V${y.toString(16)}`;
        case 0x5: return `SUB V${x.toString(16)}, V${y.toString(16)}`;
        case 0x6: return `SHR V${x.toString(16)}`;
        case 0x7: return `SUBN V${x.toString(16)}, V${y.toString(16)}`;
        case 0xE: return `SHL V${x.toString(16)}`;
      }
      return 'UNK 8xy';
    case 0x9000: return `SNE V${x.toString(16)}, V${y.toString(16)}`;
    case 0xA000: return `LD I, 0x${nnn.toString(16).toUpperCase()}`;
    case 0xB000: return `JP V0, 0x${nnn.toString(16).toUpperCase()}`;
    case 0xC000: return `RND V${x.toString(16)}, ${h(nn)}`;
    case 0xD000: return `DRW V${x.toString(16)}, V${y.toString(16)}, ${n}`;
    case 0xE000:
      if(nn===0x9E) return `SKP V${x.toString(16)}`;
      if(nn===0xA1) return `SKNP V${x.toString(16)}`;
      return 'UNK Ex';
    case 0xF000:
      switch(nn){
        case 0x07: return `LD V${x.toString(16)}, DT`;
        case 0x0A: return `LD V${x.toString(16)}, K`;
        case 0x15: return `LD DT, V${x.toString(16)}`;
        case 0x18: return `LD ST, V${x.toString(16)}`;
        case 0x1E: return `ADD I, V${x.toString(16)}`;
        case 0x29: return `LD F, V${x.toString(16)}`;
        case 0x33: return `LD B, V${x.toString(16)}`;
        case 0x55: return `LD [I], V0-V${x.toString(16)}`;
        case 0x65: return `LD V0-V${x.toString(16)}, [I]`;
      }
      return 'UNK Fx';
    default: return 'UNK';
  }
}

/* ===================== UI / DRIVER ===================== */

const cpu = new Chip8();

const screenCanvas = document.getElementById('screen');
const SCALE = 10;
screenCanvas.width = 64*SCALE;
screenCanvas.height = 32*SCALE;
const ctx = screenCanvas.getContext('2d');

function renderDisplay(){
  ctx.fillStyle = '#000';
  ctx.fillRect(0,0,screenCanvas.width,screenCanvas.height);
  ctx.fillStyle = '#9ae6b4';
  for(let yy=0; yy<32; yy++){
    for(let xx=0; xx<64; xx++){
      if(cpu.display[yy*64+xx]){
        ctx.fillRect(xx*SCALE, yy*SCALE, SCALE, SCALE);
      }
    }
  }
}

// --- audio (simple beep using WebAudio, generated inline, no external asset) ---
let actx = null, oscNode = null, gainNode = null, soundPlaying=false;
function ensureAudio(){
  if(!actx){
    const AC = window.AudioContext || window.webkitAudioContext;
    if(!AC) return;
    actx = new AC();
  }
}
function startBeep(){
  if(!document.getElementById('soundToggle').checked) return;
  ensureAudio();
  if(!actx || soundPlaying) return;
  oscNode = actx.createOscillator();
  gainNode = actx.createGain();
  oscNode.type = 'square';
  oscNode.frequency.value = 440;
  gainNode.gain.value = 0.05;
  oscNode.connect(gainNode).connect(actx.destination);
  oscNode.start();
  soundPlaying = true;
}
function stopBeep(){
  if(soundPlaying && oscNode){
    oscNode.stop();
    oscNode.disconnect();
    gainNode.disconnect();
    soundPlaying = false;
  }
}

// --- keypad UI ---
const keypadEl = document.getElementById('keypad');
const keyButtons = {};
KEYPAD_LAYOUT.flat().forEach(label=>{
  const btn = document.createElement('button');
  btn.textContent = label;
  const hex = KEYMAP[label.toLowerCase()];
  keyButtons[hex] = btn;
  const press = (e)=>{ e.preventDefault(); setKey(hex,true); btn.classList.add('down'); };
  const release = (e)=>{ e.preventDefault(); setKey(hex,false); btn.classList.remove('down'); };
  btn.addEventListener('mousedown', press);
  btn.addEventListener('mouseup', release);
  btn.addEventListener('mouseleave', release);
  btn.addEventListener('touchstart', press, {passive:false});
  btn.addEventListener('touchend', release, {passive:false});
  keypadEl.appendChild(btn);
});

function setKey(hex, down){
  cpu.keys[hex] = down ? 1 : 0;
  if(down) cpu.provideKey(hex);
  const btn = keyButtons[hex];
  if(btn) btn.classList.toggle('down', down);
}

window.addEventListener('keydown', (e)=>{
  const k = KEYMAP[e.key.toLowerCase()];
  if(k !== undefined){ setKey(k, true); }
});
window.addEventListener('keyup', (e)=>{
  const k = KEYMAP[e.key.toLowerCase()];
  if(k !== undefined){ setKey(k, false); }
});

// --- controls ---
let running = false;
let ipf = 10;
const speedSlider = document.getElementById('speed');
const speedVal = document.getElementById('speedVal');
speedSlider.addEventListener('input', ()=>{
  ipf = parseInt(speedSlider.value,10);
  speedVal.textContent = ipf;
});

function setStatus(msg){ document.getElementById('status').textContent = msg; }

document.getElementById('btnRun').addEventListener('click', ()=>{
  running = true;
  setStatus('Running...');
  document.getElementById('btnRun').classList.add('active');
  document.getElementById('btnPause').classList.remove('active');
});
document.getElementById('btnPause').addEventListener('click', ()=>{
  running = false;
  setStatus('Paused.');
  document.getElementById('btnPause').classList.add('active');
  document.getElementById('btnRun').classList.remove('active');
});
document.getElementById('btnStep').addEventListener('click', ()=>{
  running = false;
  document.getElementById('btnPause').classList.add('active');
  document.getElementById('btnRun').classList.remove('active');
  cpu.step();
  renderDisplay();
  updateDebugger();
  setStatus('Single-stepped.');
});
document.getElementById('btnReset').addEventListener('click', ()=>{
  cpu.loadRom(currentRom);
  renderDisplay();
  updateDebugger();
  setStatus('Reset.');
});
document.getElementById('btnLoadDemo').addEventListener('click', ()=>{
  currentRom = DEMO_ROM;
  cpu.loadRom(currentRom);
  renderDisplay();
  updateDebugger();
  setStatus('Demo ROM loaded. Press Run, then Q / E to move the sprite.');
});
document.getElementById('fileInput').addEventListener('change', (e)=>{
  const file = e.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = (ev)=>{
    const bytes = new Uint8Array(ev.target.result);
    currentRom = bytes;
    cpu.loadRom(currentRom);
    renderDisplay();
    updateDebugger();
    setStatus('Loaded ROM: '+file.name+' ('+bytes.length+' bytes).');
  };
  reader.readAsArrayBuffer(file);
});

let currentRom = DEMO_ROM;
cpu.loadRom(currentRom);

/* ===================== DEBUGGER PANEL ===================== */
const dbgPC = document.getElementById('dbgPC');
const dbgI = document.getElementById('dbgI');
const dbgDT = document.getElementById('dbgDT');
const dbgST = document.getElementById('dbgST');
const curInstr = document.getElementById('curInstr');
const dbgRegs = document.getElementById('dbgRegs');
const stackEl = document.getElementById('stack');

function hex4(v){ return '0x'+v.toString(16).toUpperCase().padStart(4,'0'); }
function hex2(v){ return '0x'+v.toString(16).toUpperCase().padStart(2,'0'); }

function updateDebugger(){
  dbgPC.textContent = hex4(cpu.pc);
  dbgI.textContent = hex4(cpu.I);
  dbgDT.textContent = cpu.dt;
  dbgST.textContent = cpu.st;
  curInstr.textContent = cpu.lastOpcode ? (hex4(cpu.lastOpcode)+'  '+disassemble(cpu.lastOpcode)) : '-';

  let regsHtml = '';
  for(let i=0;i<16;i++){
    regsHtml += `<div>V${i.toString(16).toUpperCase()} = ${hex2(cpu.V[i])}</div>`;
  }
  dbgRegs.innerHTML = regsHtml;

  if(cpu.stack.length===0){
    stackEl.innerHTML = '<span class="small">(empty)</span>';
  } else {
    stackEl.innerHTML = cpu.stack.slice().reverse().map((v,idx)=>
      `<div>[${cpu.stack.length-1-idx}] ${hex4(v)}</div>`).join('');
  }
}

/* ===================== MAIN LOOP (60Hz timers, adjustable IPF) ===================== */
let lastTime = 0;
const FRAME_MS = 1000/60;
let acc = 0;

function frame(ts){
  requestAnimationFrame(frame);
  if(!lastTime) lastTime = ts;
  const dt = ts - lastTime;
  lastTime = ts;
  acc += dt;

  while(acc >= FRAME_MS){
    if(running){
      for(let i=0;i<ipf;i++){
        if(cpu.waitingKeyReg>=0) break; // blocked waiting for keypress
        cpu.step();
      }
      cpu.tickTimers();
    }
    acc -= FRAME_MS;
  }

  if(running){
    if(cpu.st>0) startBeep(); else stopBeep();
  } else {
    stopBeep();
  }

  if(cpu.drawFlag){
    renderDisplay();
    cpu.drawFlag = false;
  }
  updateDebugger();
}
requestAnimationFrame(frame);

renderDisplay();
updateDebugger();
setStatus('Demo ROM loaded. Press Run, then Q (left) / E (right) to move the sprite.');

})();
</script>
